      "keystrokes": "cat > myproject/myproject.py << 'PYEOF'\n\"\"\"CRUD User Management with Reflex.\"\"\"\n\nimport reflex as rx\n\nfrom rxconfig import config\n\n\nclass User(rx.Model, table=True):\n    \"\"\"User model stored in the SQLite database.\"\"\"\n\n    username: str\n    email: str\n    is_active: bool = True\n\n\nclass State(rx.State):\n    \"\"\"The app state.\"\"\"\n\n    users: list[User] = []\n    username: str = \"\"\n    email: str = \"\"\n\n    def load_users(self):\n        \"\"\"Load all users from the database.\"\"\"\n        with rx.session() as session:\n            self.users = session.exec(User.select()).all()\n\n    def create_user(self):\n        \"\"\"Create a new user.\"\"\"\n        with rx.session() as session:\n            user = User(\n                username=self.username,\n                email=self.email,\n                is_active=True,\n            )\n            session.add(user)\n            session.commit()\n            self.username = \"\"\n            self.email = \"\"\n        self.load_users()\n\n    def delete_user(self, user_id: int):\n        \"\"\"Delete a user by id.\"\"\"\n        with rx.session() as session:\n            user = session.get(User, user_id)\n            if user is not None:\n                session.delete(user)\n                session.commit()\n        self.load_users()\n\n    def toggle_active(self, user_id: int):\n        \"\"\"Toggle the is_active flag of a user.\"\"\"\n        with rx.session() as session:\n            user = session.get(User, user_id)\n            if user is not None:\n                user.is_active = not user.is_active\n                session.add(user)\n                session.commit()\n        self.load_users()\n\n\ndef _user_row(user: User) -> rx.Component:\n    return rx.table.row(\n        rx.table.cell(user.username),\n        rx.table.cell(user.email),\n        rx.table.cell(rx.cond(user.is_active, rx.text(\"True\"), rx.text(\"False\"))),\n        rx.table.cell(\n            rx.hstack(\n                rx.button(\n                    \"Toggle\",\n                    on_click=lambda: State.toggle_active(user.id),\n                    size=\"2\",\n                ),\n                rx.button(\n                    \"Delete\",\n                    on_click=lambda: State.delete_user(user.id),\n                    size=\"2\",\n                    color_scheme=\"red\",\n                ),\n                spacing=\"2\",\n            )\n        ),\n    )\n\n\ndef index() -> rx.Component:\n    return rx.container(\n        rx.color_mode.button(position=\"top-right\"),\n        rx.vstack(\n            rx.heading(\"User Management\", size=\"7\"),\n            rx.vstack(\n                rx.heading(\"Create User\", size=\"4\"),\n                rx.input(\n                    placeholder=\"Username\",\n                    value=State.username,\n                    on_change=State.set_username,\n                ),\n                rx.input(\n                    placeholder=\"Email\",\n                    value=State.email,\n                    on_change=State.set_email,\n                ),\n                rx.button(\"Create\", on_click=State.create_user),\n                spacing=\"2\",\n                align=\"stretch\",\n            ),\n            rx.table.root(\n                rx.table.header(\n                    rx.table.row(\n                        rx.table.column_header_cell(\"Username\"),\n                        rx.table.column_header_cell(\"Email\"),\n                        rx.table.column_header_cell(\"Active\"),\n                        rx.table.column_header_cell(\"Actions\"),\n                    ),\n                ),\n                rx.table.body(\n                    rx.foreach(State.users, _user_row),\n                ),\n            ),\n            spacing=\"5\",\n        ),\n        on_mount=State.load_users,\n    )\n\n\napp = rx.App()\napp.add_page(index)\nPYEOF\n",
